CREATE TABLE `t_secom_workhistory` (
  `WorkDate` varchar(8) NOT NULL,
  `CardNo` varchar(64) NOT NULL,
  `CardFullData` varchar(64) DEFAULT NULL,
  `JuminNo` varchar(64) DEFAULT NULL,
  `Name` varchar(64) DEFAULT NULL,
  `Sabun` varchar(64) DEFAULT NULL,
  `Company` varchar(3) DEFAULT NULL,
  `Department` varchar(3) DEFAULT NULL,
  `Team` varchar(3) DEFAULT NULL,
  `Part` varchar(3) DEFAULT NULL,
  `Grade` varchar(3) DEFAULT NULL,
  `DetailGrade` varchar(3) DEFAULT NULL,
  `WorkGroupCode` varchar(3) DEFAULT NULL,
  `WorkGroupName` varchar(64) DEFAULT NULL,
  `ScheduleID` varchar(3) DEFAULT NULL,
  `ScheduleName` varchar(64) DEFAULT NULL,
  `ScheduleType` int DEFAULT NULL,
  `WorkType` int DEFAULT NULL,
  `bWS` int DEFAULT NULL,
  `bWC` int DEFAULT NULL,
  `WSTime` varchar(14) DEFAULT NULL,
  `WCTime` varchar(14) DEFAULT NULL,
  `PWType` int DEFAULT NULL,
  `PWTime` int DEFAULT NULL,
  `OWTime` int DEFAULT NULL,
  `NWTime` int DEFAULT NULL,
  `TotalWorkTime` int DEFAULT NULL,
  `NormalWorkTime` int DEFAULT NULL,
  `HWTime` int DEFAULT NULL,
  `bLate` int DEFAULT NULL,
  `bPWC` int DEFAULT NULL,
  `bAbsent` int DEFAULT NULL,
  `LateTime` int DEFAULT NULL,
  `ModifyUser` varchar(32) DEFAULT NULL,
  `ModifyTime` varchar(14) DEFAULT NULL,
  `InsertTime` varchar(14) DEFAULT NULL,
  `UpdateTime` varchar(14) DEFAULT NULL,
  `Version` varchar(14) DEFAULT NULL,
  PRIMARY KEY (`WorkDate`,`CardNo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
